#include <array>
#include <cstddef>
#include <iostream>

template <typename T, std::size_t N>
class SpscQueue {
    static_assert(N >= 2 && (N & (N - 1)) == 0, "N must be a power of two");

public:
    bool push(const T& value) {
        if (tail_ - head_ == N) {
            return false;  // full
        }
        slots_[tail_ & (N - 1)] = value;
        ++tail_;
        return true;
    }

    bool pop(T& out) {
        if (head_ == tail_) {
            return false;  // empty
        }
        out = slots_[head_ & (N - 1)];
        ++head_;
        return true;
    }

private:
    std::array<T, N> slots_{};
    std::size_t head_ = 0;  // pops so far, so head_ & (N - 1) is the next slot to read
    std::size_t tail_ = 0;  // pushes so far, so tail_ & (N - 1) is the next slot to write
};

int main() {
    SpscQueue<int, 4> q;
    for (int price = 101; price <= 105; ++price) {
        std::cout << "push " << price << (q.push(price) ? " ok" : " full") << '\n';
    }
    int out = 0;
    for (int i = 0; i < 2; ++i) {
        q.pop(out);
        std::cout << "pop " << out << '\n';
    }
    for (int price = 106; price <= 107; ++price) {
        std::cout << "push " << price << (q.push(price) ? " ok" : " full") << '\n';
    }
    std::cout << "drain";
    while (q.pop(out)) {
        std::cout << ' ' << out;
    }
    std::cout << '\n' << "pop again " << (q.pop(out) ? "ok" : "empty") << '\n';
    return 0;
}

