// -O2
#include <array>
#include <atomic>
#include <cstddef>
#include <iostream>
#include <thread>

template <typename T, std::size_t N>
class SpscQueue {
    static_assert(N >= 2 && (N & (N - 1)) == 0, "N must be a power of two");

public:
    bool push(const T& value) {  // the producer thread only
        const std::size_t tail = tail_.load(std::memory_order_relaxed);
        if (tail - head_.load(std::memory_order_acquire) == N) {
            return false;  // full
        }
        slots_[tail & (N - 1)] = value;
        tail_.store(tail + 1, std::memory_order_release);  // publish the slot
        return true;
    }

    bool pop(T& out) {  // the consumer thread only
        const std::size_t head = head_.load(std::memory_order_relaxed);
        if (head == tail_.load(std::memory_order_acquire)) {
            return false;  // empty
        }
        out = slots_[head & (N - 1)];
        head_.store(head + 1, std::memory_order_release);  // hand the slot back
        return true;
    }

private:
    std::array<T, N> slots_{};
    std::atomic<std::size_t> head_{0};
    std::atomic<std::size_t> tail_{0};
};

int main() {
    static_assert(std::atomic<std::size_t>::is_always_lock_free);
    SpscQueue<long long, 1024> q;
    const long long n = 1000000;
    long long received = 0;
    long long sum = 0;
    long long out_of_order = 0;

    std::thread consumer([&] {
        long long value = 0;
        while (received < n) {
            if (q.pop(value)) {
                ++received;
                sum += value;
                if (value != received) {
                    ++out_of_order;
                }
            }
        }
    });
    std::thread producer([&] {
        for (long long i = 1; i <= n; ++i) {
            while (!q.push(i)) {
                // full: spin until the consumer frees a slot
            }
        }
    });
    producer.join();
    consumer.join();

    std::cout << "received " << received << '\n';
    std::cout << "sum " << sum << '\n';
    std::cout << "out of order " << out_of_order << '\n';
    return 0;
}

