#include <array>
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <thread>

struct Tick {
    int64_t ts_ns;          // nanoseconds since midnight
    double bid, ask;        // prices
    double bid_sz, ask_sz;  // sizes
};

template <typename T, std::size_t N>
class SpscQueue {
    static_assert(N >= 2 && (N & (N - 1)) == 0, "N must be a power of two");

public:
    bool push(const T& value) {  // the producer thread only
        const std::size_t tail = tail_.load(std::memory_order_relaxed);
        if (tail - head_seen_ == N) {
            head_seen_ = head_.load(std::memory_order_acquire);  // looks full: look again
            if (tail - head_seen_ == N) {
                return false;
            }
        }
        slots_[tail & (N - 1)] = value;
        tail_.store(tail + 1, std::memory_order_release);
        return true;
    }

    bool pop(T& out) {  // the consumer thread only
        const std::size_t head = head_.load(std::memory_order_relaxed);
        if (head == tail_seen_) {
            tail_seen_ = tail_.load(std::memory_order_acquire);  // looks empty: look again
            if (head == tail_seen_) {
                return false;
            }
        }
        out = slots_[head & (N - 1)];
        head_.store(head + 1, std::memory_order_release);
        return true;
    }

private:
    alignas(128) std::atomic<std::size_t> head_{0};  // the consumer's line
    std::size_t tail_seen_ = 0;
    alignas(128) std::atomic<std::size_t> tail_{0};  // the producer's line
    std::size_t head_seen_ = 0;
    alignas(128) std::array<T, N> slots_{};
};

int main() {
    SpscQueue<Tick, 1024> q;
    std::cout << "sizeof " << sizeof(q) << ", alignof " << alignof(SpscQueue<Tick, 1024>) << '\n';
    const int n = 1000000;
    int received = 0;
    uint64_t checksum = 0;
    std::thread consumer([&] {
        Tick t{};
        while (received < n) {
            if (q.pop(t)) {
                ++received;
                checksum = checksum * 31 + static_cast<uint64_t>(t.ts_ns);  // order matters
            }
        }
    });
    std::thread producer([&] {
        for (int i = 0; i < n; ++i) {
            const Tick t{34200000000000LL + i * 250LL, 100.25, 100.26, 5.0, 3.0};  // from 9:30
            while (!q.push(t)) {}
        }
    });
    producer.join();
    consumer.join();
    std::cout << "ticks " << received << ", checksum " << checksum << '\n';
    return 0;
}

